#!/usr/bin/env bash
# Print the three most frequent IP addresses in access.log.
# Ties are broken by first appearance in the log.
set -eu

awk '
    {
        ip = $1
        count[ip]++
        if (!(ip in first)) {
            first[ip] = NR
        }
    }
    END {
        n = 0
        for (ip in count) {
            n++
            count[n] = count[ip]
            order[n] = ip
        }
        # Stable insertion sort by (-count, first appearance)
        for (i = 2; i <= n; i++) {
            c = count[i]; o = order[i]; f = first[o]
            j = i - 1
            while (j >= 1 && (count[j] < c || (count[j] == c && first[order[j]] > f))) {
                count[j+1] = count[j]
                order[j+1] = order[j]
                j--
            }
            count[j+1] = c
            order[j+1] = o
        }
        top = (n < 3) ? n : 3
        for (i = 1; i <= top; i++) print order[i]
    }
' access.log
